  ('70-vinh-long', 'target', null::text),
  ('70-vinh-long', 'source', 'Vĩnh Long'),
  ('70-vinh-long', 'source', 'Long An')
) as v(province_slug, role, source_name)
join public.geo_datasets d on d.code = 'vn-admin-2025-07-01'
join public.geo_units u on u.dataset_id = d.id and u.slug = v.province_slug
join public.geo_events e on e.dataset_id = d.id and e.metadata->>'province_slug' = v.province_slug;

-- ── 10. Nguồn tham chiếu ─────────────────────────────────────────────────────
insert into public.geo_sources (dataset_id, title, publisher, url, accessed_at, sort_order)
select d.id, v.title, v.publisher, v.url, v.accessed_at::date, v.sort_order
from (values
  ('Nghị quyết 202/2025/QH15 (12/6/2025) – Sắp xếp ĐVHC cấp tỉnh', 'Quốc hội', null, null::date, 1),
  ('34 Nghị quyết của UBTVQH (1654–NQ-UBTVQH15 đến 1687/NQ-UBTVQH15, 16/6/2025)', 'Ủy ban Thường vụ Quốc hội', null, null::date, 2),
  ('Quyết định 19/2025/QĐ-TTg (30/6/2025) – Bảng mã số đơn vị hành chính', 'Thủ tướng Chính phủ', null, null::date, 3),
  ('Chính phủ – xaydungchinhsach.chinhphu.vn – Toàn văn 34 nghị quyết cấp xã', 'Chính phủ', 'https://xaydungchinhsach.chinhphu.vn', null::date, 4),
  ('provinces.open-api.vn — API v2, depth=2', 'Open API Vietnam', 'https://provinces.open-api.vn/api/v2/?depth=2', '2026-10-21', 5)
) as v(title, publisher, url, accessed_at, sort_order)
join public.geo_datasets d on d.code = 'vn-admin-2025-07-01';

commit;

